#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 200

typedef struct ListNode {
    int ele;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));
    link->size = 0;
    link->head = NULL;
    link->tail = NULL;
    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));
    node->ele = ele;
    node->prev = NULL;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        node->prev = link->tail;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList *link) {
    if (link->size == 0) exit(-1);

    ListNode *removed = link->head;

    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
        link->head->prev = NULL;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}

int removeLast_LinkedList(LinkedList *link) {
    if (link->size == 0) exit(-1);

    ListNode *removed = link->tail;

    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->tail = link->tail->prev;
        link->tail->next = NULL;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}

int main() {
    int inputs[MAX_SIZE];
    int inputs_size = 0;

    while (scanf("%d", &inputs[inputs_size++])) {
        if (getchar() != ',') break;
    }

    int outputs[MAX_SIZE];
    int outputs_size = 0;

    while (scanf("%d", &outputs[outputs_size++])) {
        if (getchar() != ',') break;
    }

    // 利用队列结构模拟圆桶
    LinkedList *queue = new_LinkedList();
    // outputs[index]是要被取出的篮球的编号
    int index = 0;

    // 记录题解
    char res[MAX_SIZE] = {'\0'};
    int res_size = 0;

    for (int i = 0; i < inputs_size; i++) {
        // 按照放入顺序，从圆桶右边放入
        addLast_LinkedList(queue, inputs[i]);

        // 然后开始尝试取出
        while (queue->size > 0) {
            // 圆桶左边的篮球的编号
            int left = queue->head->ele;
            // 圆桶右边的篮球的编号
            int right = queue->tail->ele;

            if (left == outputs[index]) {
                // 优先比较圆桶左边的篮球是不是当前要取出的篮球，优先左边的原因是：当桶只有一个篮球的情况下，必须从左边取出
                res[res_size++] = 'L';
                removeFirst_LinkedList(queue);
                index++;
            } else if (right == outputs[index]) {
                // 比较圆桶右边的篮球是不是当前要取出的篮球
                res[res_size++] = 'R';
                removeLast_LinkedList(queue);
                index++;
            } else {
                // 如果圆桶左右两边都不是要取出的球，则本轮取出流程结束
                break;
            }
        }
    }

    // 最终如果圆桶空了，则说明所有球都取出了，否则按照给定要求无法取出所有球
    if (queue->size != 0) {
        puts("NO");
    } else {
        puts(res);
    }

    return 0;
}
